def evaluate(x):  # 返回多目标
    return np.array([f1(x), f2(x), f3(x), f4(x)])

def scalarize(fvec, method="wsum", **kw):
    z = normalize(fvec, **kw)      # Min-Max 或 Z-score
    if method == "wsum":
        w = kw.get("w", np.ones(len(z))/len(z))
        return float((w*z).sum())
    elif method == "tcheby":
        w = kw["w"]; zstar = kw["zstar"]
        return float(np.max(w * np.abs(z - zstar)))
    elif method == "prod":
        eps = kw.get("eps", 1e-9)
        return float(np.prod(z + eps))
    else:
        raise ValueError

