```js
// 全局变量提前声明（socket/objIndividuals/individualDesigns/...）
let socket, objIndividuals=[], individualDesigns=[], objClusters=[], maxGen=0, filterOneGen=false, selectedGen=1, saveSelected;

ket, objIndividuals=[], individualDesigns=[], objClusters=[], maxGen=0, filterOneGen=false, selectedGen=1, saveSelected;

// 全局映射：合并顺序中的“全局点号” → {第几代, 代内第几个}
function resolvePointToGenIdx3D(globalIdx, mode='Individuals', single=false) {
  if (single) return { genIndex: selectedGen-1, idxInGen: globalIdx };
  const gens = (mode==='Clusters') ? objClusters : objIndividuals;
  let offset=0;
  for (let g=0; g<gens.length; g++){
    const dict = gens[g] || {};
    const n = (dict["weight_norm"] || []).length;
    if (globalIdx < offset + n) return { genIndex:g, idxInGen: globalIdx - offset };
    offset += n;
  }
  return null;
}

