  const x = dataDict["weight_norm"] || [];
  const y = dataDict["leg_stress_dev"] || [];
  const z = dataDict["brace_stress_dev"] || [];
  const c = dataDict["freq_penalty"] || Array(x.length).fill(0);
  const n = Math.min(x.length, y.length, z.length, c.length);
  return { x: x.slice(0,n), y: y.slice(0,n), z: z.slice(0,n), c: c.slice(0,n), n };
}

