function computeParetoMaskFromDict(D) {
  const keys = Object.keys(D); if (!keys.length) return [];
  const N = D[keys[0]].length, M = keys.length;
  const A = Array.from({length:N},(_,i)=>keys.map(k=>D[k][i]));
  const nd = Array(N).fill(true);
  for (let i=0;i<N;i++){
    if(!nd[i]) continue;
    for (let j=0;j<N;j++){
      if(i===j) continue;
      let all_le=true, any_lt=false;
      for(let m=0;m<M;m++){ const a=A[i][m], b=A[j][m];
        if (b<a) any_lt=true; if (b>a){ all_le=false; break; }
      }
      if(all_le && any_lt){ nd[i]=false; break; }
    }
  }
  return nd;
}
